urlset:
{%- for file in pages -%}
    {% if not file.page.is_link and (file.page.abs_url or file.page.canonical_url) %}

         {% if file.page.canonical_url %}{{file.page.canonical_url|e}}{% else %}{{file.page.abs_url|e}}{% endif %}
         {% set modified = file.page.pixel_lab_lastmod if file.page.pixel_lab_lastmod is defined else file.page.update_date %}
         {% if modified %}{{modified|e}}{% endif %}

    {%- endif -%}
{% endfor %}
